const contactEmail='gm@xmsuny.com';const projectForm=document.querySelector('[data-project-form]');const modelParam=new URLSearchParams(location.search).get('model');if(modelParam&&projectForm?.elements.model)projectForm.elements.model.value=modelParam;projectForm?.addEventListener('submit',(event)=>{event.preventDefault();const data=new FormData(event.currentTarget);const text=['SUNY Project Inquiry','',...Array.from(data.entries()).map(([key,value])=>`${key}: ${value}`)].join('\n');const subject=`SUNY Project Inquiry - ${data.get('company')||data.get('name')||'New project'}`;window.location.href=`mailto:${contactEmail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(text)}`;const note=projectForm.querySelector('[data-send-note]');if(note)note.textContent='Your email app should now be open. Review the message and send it from there.';});
